INSERT INTO `quiz_answer` VALUES (365, 179, 10, '判断', '计算机网络基础', 'TCP/IP模型将网络结构划分为七层。', NULL, '正确', '错误*', 0, 2, 0, '2026-08-17 22:22:32', 0);
INSERT INTO `quiz_answer` VALUES (366, 179, 11, '解析', '计算机网络基础', '请简述带宽与吞吐量的区别。', NULL, '宽带是流量大小，吞吐是接收发送的效率', '带宽指单位时间内能传输的最大数据量，是链路理论能力；吞吐量是实际测得的有效传输速率，受网络拥塞、设备性能等因素影响，是实际表现。', 0, 60, 0, '2026-08-17 22:22:32', 0);
INSERT INTO `quiz_answer` VALUES (367, 179, 12, '解析', '计算机网络基础', '请列举时延的四个组成部分。', NULL, '不会', '发送时延、传播时延、处理时延、排队时延。', -1, 15, 0, '2026-08-17 22:22:32', 0);
INSERT INTO `quiz_answer` VALUES (368, 179, 13, '解析', '计算机网络基础', 'OSI模型与TCP/IP模型在分层数量上有何不同？两者的核心思想有何共同点？', NULL, '应用成不一样', 'OSI模型分为七层，TCP/IP模型分为四层；两者核心思想一致，都采用分层和协议栈的方式组织网络功能。', 0, 17, 0, '2026-08-17 22:22:32', 0);
