INSERT INTO `quiz_answer` VALUES (394, 183, 9, '判断', '计算机网络基础', 'OSI模型理论完整但实现复杂，TCP/IP模型简单实用。', NULL, '错误', '正确*', 0, 0, 1, '2026-09-08 17:42:10', 0);
