INSERT INTO `quiz_answer` VALUES (396, 183, 11, '解析', '计算机网络基础', '请简述带宽与吞吐量的区别。', NULL, '不会', '带宽是链路理论上单位时间内能传输的最大数据量，单位为比特每秒；吞吐量是实际测得的有效传输速率，受网络拥塞、设备性能等因素影响。带宽是理论能力，吞吐量是实际表现。', -1, 0, 0, '2026-09-08 17:42:10', 0);
INSERT INTO `quiz_answer` VALUES (397, 183, 12, '解析', '计算机网络基础', '时延由哪几部分组成？请分别写出发送时延和传播时延的计算公式。', NULL, '不会', '时延由发送时延、传播时延、处理时延和排队时延四部分组成。发送时延＝数据长度÷带宽；传播时延＝链路长度÷信号传播速率。', -1, 0, 0, '2026-09-08 17:42:10', 0);
INSERT INTO `quiz_answer` VALUES (398, 183, 13, '解析', '计算机网络基础', '请简述OSI模型与TCP/IP模型的主要不同点。', NULL, '不会', 'OSI模型分为七层，理论完整但实现复杂；TCP/IP模型分为四层，简单实用，是互联网事实标准。两者分层数量不同，但核心思想一致，都采用分层和协议栈的方式组织网络功能。', -1, 0, 0, '2026-09-08 17:42:10', 0);
INSERT INTO `quiz_answer` VALUES (399, 183, 14, '填空', '计算机网络基础', '时延由发送时延、传播时延、处理时延和______时延四部分组成。', NULL, '不会', '排队', -1, 0, 0, '2026-09-08 17:42:10', 0);
