INSERT INTO `quiz_answer` VALUES (411, 184, 11, '解析', '计算机网络基础', '请简述带宽与吞吐量的区别，并说明为什么链路带宽为 100 Mbps 时实际吞吐量可能只有 80 Mbps。', NULL, '不会', '带宽是单位时间内能传输的最大数据量，是链路理论能力；吞吐量是实际测得的有效传输速率，会受网络拥塞、设备性能等因素影响，所以实际吞吐量可能低于理论带宽。', -1, 1, 0, '2026-09-08 18:15:52', 0);
INSERT INTO `quiz_answer` VALUES (412, 184, 12, '解析', '计算机网络基础', '请说出网络边缘与网络核心分别包括哪些设备，并说明各自的作用。', NULL, '不会', '网络边缘包括主机、服务器、移动终端等设备，负责产生数据；网络核心由路由器和交换机组成本，负责数据的高速转发和传递。', -1, 3, 0, '2026-09-08 18:15:52', 0);
INSERT INTO `quiz_answer` VALUES (413, 184, 13, '解析', '计算机网络基础', '请按从下到上的顺序写出 OSI 参考模型的七层，并简述其中物理层、数据链路层、网络层的主要功能。', NULL, '不会', '从下到上依次为物理层、数据链路层、网络层、传输层、会话层、表示层和应用层。物理层传输比特流；数据链路层负责相邻节点之间的可靠传输；网络层负责主机间的路由选择。', -1, 0, 0, '2026-09-08 18:15:52', 0);
