INSERT INTO `quiz_answer` VALUES (456, 187, 11, '解析', '计算机网络基础', '请解释带宽与吞吐量的区别，并说明为什么实际吞吐量可能低于链路带宽。', NULL, '不会', '带宽是链路单位时间内能传输的最大数据量，是理论能力；吞吐量是实际测得的有效传输速率，是实际表现。实际吞吐量会受网络拥塞、设备性能等因素影响，因此可能低于链路带宽，例如100Mbps链路实际吞吐量可能只有80Mbps。', -1, 0, 0, '2026-09-08 18:50:48', 0);
INSERT INTO `quiz_answer` VALUES (457, 187, 12, '解析', '计算机网络基础', '请说明网络边缘与网络核心分别包括哪些设备，并简述它们在通信过程中的作用。', NULL, '不会', '网络边缘包括主机、服务器和移动终端等设备，负责产生数据；网络核心由路由器和交换机组成，负责数据的高速转发，传递数据。例如家庭路由器属于网络边缘设备，上游运营商路由器属于网络核心设备。', -1, 0, 0, '2026-09-08 18:50:48', 0);
INSERT INTO `quiz_answer` VALUES (458, 187, 13, '解析', '计算机网络基础', '请简述OSI参考模型与TCP/IP参考模型的主要不同点，为什么TCP/IP模型被称为互联网事实标准？', NULL, '不会', 'OSI模型理论完整但实现复杂，分为七层；TCP/IP模型简单实用，分为四层。TCP/IP模型协议实现更直接，是互联网实际采用的标准，因此被称为互联网事实标准；两者都采用分层和协议栈方式组织网络功能，核心思想一致。', -1, 0, 0, '2026-09-08 18:50:48', 0);
INSERT INTO `quiz_answer` VALUES (459, 187, 14, '填空', '计算机网络基础', '时延由发送时延、传播时延、处理时延和______四部分组成。', NULL, '不会', '排队时延', -1, 0, 0, '2026-09-08 18:50:48', 0);
