INSERT INTO `quiz_answer` VALUES (487, 189, 12, '解析', '计算机网络基础', '比较OSI参考模型与TCP/IP参考模型在分层数量上的区别。', NULL, '不会', 'OSI参考模型分为7层，TCP/IP参考模型分为4层；OSI模型理论完整但实现复杂，TCP/IP模型简单实用，两者都采用分层和协议栈的方式组织网络功能。', -1, 0, 0, '2026-09-08 19:07:30', 0);
