INSERT INTO `quiz_answer` VALUES (501, 190, 11, '解析', '计算机网络基础', '请解释带宽与吞吐量的区别，并举例说明。', NULL, '不会', '带宽是单位时间内链路能传输的最大数据量，是理论能力；吞吐量是实际测得的有效传输速率，受网络拥塞、设备性能等因素影响。例如，一条链路带宽为100 Mbps，但实际吞吐量可能只有80 Mbps。', -1, 1, 0, '2026-09-08 21:55:31', 0);
INSERT INTO `quiz_answer` VALUES (502, 190, 12, '解析', '计算机网络基础', '计算机网络中的时延由哪几部分组成？并说明发送时延和传播时延分别与什么有关。', NULL, '不会', '时延由发送时延、传播时延、处理时延和排队时延四部分组成。发送时延等于数据长度除以带宽；传播时延等于链路长度除以信号传播速率。', -1, 0, 0, '2026-09-08 21:55:31', 0);
INSERT INTO `quiz_answer` VALUES (503, 190, 13, '解析', '计算机网络基础', '请比较OSI参考模型与TCP/IP参考模型的异同。', NULL, '不会', '两者都采用分层和协议栈的方式组织网络功能，核心思想一致。OSI模型分为七层，理论完整但实现复杂；TCP/IP模型分为四层，简单实用，是互联网事实标准。网络教学中常以OSI模型讲解原理，以TCP/IP模型分析实际协议。', -1, 0, 0, '2026-09-08 21:55:31', 0);
